      SUBROUTINE NAME10CC     FIND MATRIX ELEMENT NAME FOR CONSTRAINTCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA1C.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM10C.CIN'      INCLUDE 'RDCHAR.CIN'CC     LOCAL VARIABLESC      CHARACTER*1     FTCHAR(8)      EQUIVALENCE     (FTNAME,FTCHAR(1))CC-------------------------------------------------------------      FTNAME = BLANK      J = JCON      K = KCON      IF (J .EQ. 0 .AND. K .EQ. 0) GO TO 100      IF (J .EQ. 8) GO TO 110      IF (J .EQ. 9) GO TO 135      IF (J .EQ. 18) GO TO 550      IF (J .EQ. 100) GO TO 600      GO TO 140CC     SYSTEM LENGTH CONSTRAINTC  100 FTNAME = 'LENGTH'      GO TO 1000CC     FLOOR COORDINATE CONSTRAINTC  110 IF (K .EQ. 1) FTNAME = 'XFLOOR'      IF (K .EQ. 2) FTNAME = 'YFLOOR'      IF (K .EQ. 3) FTNAME = 'ZFLOOR'      IF (K .EQ. 4) FTNAME = 'YAW'      IF (K .EQ. 5) FTNAME = 'PITCH'      IF (K .EQ. 6) FTNAME = 'ROLL'      IF (K .EQ. 7) FTNAME = 'ELEVATIO'      GO TO 1000CC     CONSTRAINT ON ALGEBRAIC COMBINATION OF MATRIX ELEMENTSC  135 FTNAME = 'ALGEBRA'      DO 136 N = 1, NEL      II = ISTOR(N)      IF (II+1 .EQ. KCON) THEN        IF (LABEL(N) .NE. BLANK) THEN          FTNAME = LABEL(N)(1:8)          GO TO 137        ENDIF      ENDIF  136 CONTINUE  137 GO TO 1000CC     TRANSFER MATRIX CONSTRAINTSC  140 IF (J .LT. - 20) GO TO 150      IF (J .LT. - 10) GO TO 200      IF (J .LT. 0) GO TO 250      GO TO 300CC     R2 MATRIX CONSTRAINTC  150 J = - (J + 20)      IF (K .GT. 10) GO TO 180      FTCHAR(1) = 'R'      FTCHAR(2) = 'A'      FTCHAR(3) = TABLE(J+1)      FTCHAR(4) = TABLE(K+1)      GO TO 1000CC     T2 MATRIX CONSTRAINTC  180 IF (K .GT. 100) GO TO 190      KM = K      K = KM/10      M = KM - 10*K      FTCHAR(1) = 'T'      FTCHAR(2) = 'A'      FTCHAR(3) = TABLE(J+1)      FTCHAR(4) = TABLE(K+1)      FTCHAR(5) = TABLE(M+1)      GO TO 1000CC     U2 MATRIX CONSTRAINTC  190 KLM = K      K = KLM/100      LM = KLM - 100*K      LL = LM/10      M = LM - 10*LL      FTCHAR(1) = 'U'      FTCHAR(2) = 'A'      FTCHAR(3) = TABLE(J+1)      FTCHAR(4) = TABLE(K+1)      FTCHAR(5) = TABLE(LL+1)      FTCHAR(6) = TABLE(M+1)      GO TO 1000CC     AGS MACHINE CONSTRAINTC  200 J = - (J + 10)      IF (J .EQ. 1) THEN        FTNAME = 'MUX'      ELSE IF (J .EQ. 3) THEN        FTNAME = 'MUY'      ELSE IF (J .EQ. 5) THEN        IF (K .EQ. 1) FTNAME = 'PSIX'        IF (K .EQ. 3) FTNAME = 'PSIY'      ENDIF      GO TO 1000CC     R MATRIX CONSTRAINTC  250 J = - J      IF (K .GT. 10) GO TO 297      FTCHAR(1) = 'R'      FTCHAR(2) = TABLE(J+1)      FTCHAR(3) = TABLE(K+1)      GO TO 1000CC     T MATRIX CONSTRAINTC  297 IF (K .GT. 100) GO TO 298      KM = K      K = KM/10      M = KM - 10*K      FTCHAR(1) = 'T'      FTCHAR(2) = TABLE(J+1)      FTCHAR(3) = TABLE(K+1)      FTCHAR(4) = TABLE(M+1)      GO TO 1000CC     U MATRIX CONSTRAINTC  298 KLM = K      K = KLM/100      LM = KLM - 100*K      LL = LM/10      M = LM - 10*LL      FTCHAR(1) = 'U'      FTCHAR(2) = TABLE(J+1)      FTCHAR(3) = TABLE(K+1)      FTCHAR(4) = TABLE(LL+1)      FTCHAR(5) = TABLE(M+1)      GO TO 1000CC     BEAM CONSTRAINTSC  300 IF (J .EQ. K) GO TO 310      IF (J .GT. 10 .AND. J .LE. 16) GO TO 400      IF (J .GT. 20 .AND. J .LE. 26) GO TO 350      IF (J .EQ. 0 .OR. J .EQ. 7) GO TO 450      IF (J .EQ. 27) GO TO 500CC     BEAM MATRIX CONSTRAINTC      FTCHAR(1) = 'S'      FTCHAR(2) = TABLE(J+1)      FTCHAR(3) = TABLE(K+1)      GO TO 1000CC     BEAM SIZE CONSTRAINTC  310 IF (J .EQ. 1) FTNAME = 'XBEAM'      IF (J .EQ. 2) FTNAME = 'XPBEAM'      IF (J .EQ. 3) FTNAME = 'YBEAM'      IF (J .EQ. 4) FTNAME = 'YPBEAM'      IF (J .EQ. 5) FTNAME = 'LBEAM'      IF (J .EQ. 6) FTNAME = 'DELBEAM'      GO TO 1000CC     ACCELERATOR PARAMETER BEAM CONSTRAINTC  350 J = J - 20      IF (J .EQ. 1) FTNAME = 'BETAX'      IF (J .EQ. 2) FTNAME = 'ALPHAX'      IF (J .EQ. 3) FTNAME = 'BETAY'      IF (J .EQ. 4) FTNAME = 'ALPHAY'      GO TO 1000CC     BEAM CORRELATION CONSTRAINTC  400 FTCHAR(1) = 'C'      FTCHAR(2) = TABLE(J-9)      FTCHAR(3) = TABLE(K+1)      GO TO 1000CC     FIRST MOMENT CONSTRAINTC  450 IF (K .EQ. 1) FTNAME = 'XC'      IF (K .EQ. 2) FTNAME = 'XPC'      IF (K .EQ. 3) FTNAME = 'YC'      IF (K .EQ. 4) FTNAME = 'YPC'      IF (K .EQ. 5) FTNAME = 'DLC'      IF (K .EQ. 6) FTNAME = 'DELC'      GO TO 1000CC     CONSTRAINT ON ACCELERATOR FUNCTION ETAC  500 IF (K .EQ. 1) FTNAME = 'ETAX'      IF (K .EQ. 2) FTNAME = 'DETAX'      IF (K .EQ. 3) FTNAME = 'ETAY'      IF (K .EQ. 4) FTNAME = 'DETAY'      GO TO 1000CC     SEXTUPOLE STRENGTH LIMITSC  550 FTNAME(1:7) = 'SEXTLIM'      GO TO 1000CC     NUMERICAL CONSTANTC  600 FTNAME = 'CONSTANT'      GO TO 1000C 1000 RETURN      END